"use client"

import {
  ColumnFiltersState,
  ColumnOrderState,
  ColumnSizingState,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  PaginationState,
  RowSelectionState,
  SortingState,
  Updater,
  useReactTable,
  VisibilityState,
} from "@tanstack/react-table"
import { Download, Loader2, X } from "lucide-react"
import * as React from "react"
import { createPortal } from "react-dom"
import * as XLSX from "xlsx"

import { TsLocale, useTsLocale } from "@/components/ts-web-ui/locale"
import { Button } from "@/components/ui/button"

import { generateColumns, TsTableColumnDef, TsTableRowAction } from "./columns"
import { loadPersistedTableState, savePersistedTableState } from "./persistence"
import { TsTablePagination } from "./ts-table-pagination"
import { TsTableToolbar } from "./ts-table-toolbar"
import { TsTableView } from "./ts-table-view"

export type { TsTableColumnDef } from "./columns"

export interface ImportResult {
  added: number
  updated: number
  rejected: number
  skipped: number
  rejectedRowsData?: Record<string, unknown>[]
  /**
   * Optional plain-text error protocol (one reason per line). When set, the import results dialog
   * shows a "Download error log" button that saves it as a `.txt` file.
   */
  errorLog?: string
}

export interface TsTableProps<TData extends Record<string, unknown> = Record<string, unknown>> {
  data: TData[]
  columnDefinitions: TsTableColumnDef[]
  title?: string
  showFulltext?: boolean
  showCreateButton?: boolean
  showImportButton?: boolean
  showExportButton?: boolean
  showColumnSelector?: boolean
  enableSelection?: boolean
  enableSorting?: boolean
  enableFiltering?: boolean
  enablePagination?: boolean
  enableRowMenu?: boolean
  enableClickableRows?: boolean
  enableClickableColumns?: boolean
  enableColumnResizing?: boolean
  enableColumnReordering?: boolean
  unhideableColumns?: string[]
  onRowClick?: (row: TData, columnKey?: string) => void
  onCreateClick?: () => void
  onAction?: (action: string, row: TData) => void
  onImport?: (data: Record<string, unknown>[]) => void
  /**
   * Open import pipeline: receive the raw selected File and parse it yourself (UTF-8, string
   * cells, all columns). When set, the built-in XLSX parsing/column-filtering is skipped and
   * this takes precedence over onImport.
   */
  onImportFile?: (file: File) => void | Promise<void>
  importResult?: ImportResult | null
  onImportResultClose?: () => void
  onDataChange?: (data: TData[]) => void
  onSelectionChange?: (selectedRows: TData[]) => void
  pageSize?: number
  pageSizeOptions?: number[]
  singleItemActions?: string // "action/Label,..."
  multipleItemsActions?: string // "action/Label,..."
  onBulkAction?: (action: string, rows: TData[]) => void
  columnsRequiredForImport?: string[]
  predefinedFilters?: Record<string, unknown>
  getRowId?: (row: TData) => string
  initialRowSelection?: Record<string, boolean>
  /**
   * When set, the table view state (sorting, filters, column visibility/order/sizing, global
   * filter and pagination) is persisted to localStorage under this key and restored on mount —
   * e.g. so settings survive navigating to a detail page and back.
   */
  persistStateKey?: string
  /**
   * Initial sort applied on mount. The user can freely re-sort afterwards; this only seeds the
   * starting sort state (e.g. newest records first). Persisted sorting (when persistStateKey is
   * set) takes precedence.
   */
  defaultSorting?: SortingState
  locale?: string | TsLocale
}

function ImportResultDialog({
  result,
  columnDefinitions,
  onClose,
  t,
}: {
  result: ImportResult
  columnDefinitions: TsTableColumnDef[]
  onClose: () => void
  t: TsLocale["strings"]["table"]
}) {
  const saveRejectedRows = () => {
    const data = result.rejectedRowsData
    if (!data || data.length === 0) return
    const headers = columnDefinitions.map((c) => c.key)
    const aoa = [headers, ...data.map((row) => headers.map((h) => row[h] ?? ""))]
    const ws = XLSX.utils.aoa_to_sheet(aoa)
    const wb = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(wb, ws, "Rejected")
    const d = new Date()
    const pad = (n: number) => String(n).padStart(2, "0")
    XLSX.writeFile(
      wb,
      `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} Rejected rows.xlsx`
    )
  }

  const saveErrorLog = () => {
    if (!result.errorLog) return
    const blob = new Blob([result.errorLog], { type: "text/plain;charset=utf-8" })
    const url = URL.createObjectURL(blob)
    const d = new Date()
    const pad = (n: number) => String(n).padStart(2, "0")
    const anchor = document.createElement("a")
    anchor.href = url
    anchor.download = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} import-errors.txt`
    anchor.click()
    URL.revokeObjectURL(url)
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <div className="bg-background border rounded-lg shadow-lg p-6 w-[400px] max-w-[90vw]">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-lg font-semibold">{t.importResults}</h3>
          <button type="button" onClick={onClose} className="p-1 hover:bg-accent rounded-sm">
            <X className="h-4 w-4" />
          </button>
        </div>
        <div className="space-y-2 text-sm">
          <div className="flex justify-between">
            <span>{t.added}:</span>
            <span className="font-medium">{result.added}</span>
          </div>
          <div className="flex justify-between">
            <span>{t.updated}:</span>
            <span className="font-medium">{result.updated}</span>
          </div>
          <div className="flex justify-between">
            <span>{t.rejected}:</span>
            <span className="font-medium text-destructive">{result.rejected}</span>
          </div>
          <div className="flex justify-between">
            <span>{t.skipped}:</span>
            <span className="font-medium">{result.skipped}</span>
          </div>
        </div>
        <div className="flex justify-end gap-2 mt-6">
          {result.errorLog && result.errorLog.trim().length > 0 && (
            <Button variant="outline" size="sm" onClick={saveErrorLog}>
              <Download className="h-4 w-4 mr-1.5" />
              {t.downloadErrorLog}
            </Button>
          )}
          {result.rejected > 0 && result.rejectedRowsData && result.rejectedRowsData.length > 0 && (
            <Button variant="outline" size="sm" onClick={saveRejectedRows}>
              <Download className="h-4 w-4 mr-1.5" />
              {t.saveRejectedRows}
            </Button>
          )}
          <Button size="sm" onClick={onClose}>
            {t.close}
          </Button>
        </div>
      </div>
    </div>
  )
}

export function TsTable<TData extends Record<string, unknown> = Record<string, unknown>>({
  data: initialData,
  columnDefinitions,
  title,
  showFulltext = true,
  showCreateButton = true,
  showImportButton = true,
  showExportButton = true,
  showColumnSelector = true,
  enableSelection = true,
  enableSorting = true,
  enableFiltering = true,
  enablePagination = true,
  enableRowMenu = true,
  enableClickableRows = true,
  enableClickableColumns = false,
  enableColumnResizing = true,
  enableColumnReordering = true,
  unhideableColumns = [],
  onRowClick,
  onCreateClick,
  onAction,
  onImport,
  onImportFile,
  importResult = null,
  onImportResultClose,
  onDataChange,
  onSelectionChange,
  pageSize = 10,
  pageSizeOptions = [5, 10, 20, 50, 100],
  singleItemActions,
  multipleItemsActions,
  onBulkAction,
  columnsRequiredForImport,
  predefinedFilters,
  getRowId,
  initialRowSelection,
  persistStateKey,
  defaultSorting,
  locale: localeProp,
}: TsTableProps<TData>) {
  const locale = useTsLocale(localeProp)
  const t = locale.strings.table
  const [data, setData] = React.useState(initialData)

  // Restore any persisted view state once on mount.
  const persisted = React.useMemo(() => loadPersistedTableState(persistStateKey), [persistStateKey])

  // Persisted sorting wins; otherwise seed from defaultSorting (if provided).
  const [sorting, setSorting] = React.useState<SortingState>(
    () => persisted?.sorting ?? defaultSorting ?? []
  )

  const initialPredefinedFilters = React.useMemo(() => {
    if (!predefinedFilters) return {} as Record<string, string>
    return Object.fromEntries(
      Object.entries(predefinedFilters).map(([id, value]) => [id, String(value)])
    )
  }, [predefinedFilters])

  // Initialize filters from persisted state, falling back to predefined filters.
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>(() => {
    if (persisted?.columnFilters) return persisted.columnFilters
    return Object.entries(initialPredefinedFilters).map(([id, value]) => ({ id, value }))
  })
  const touchedPredefinedFilterKeysRef = React.useRef<Set<string>>(new Set())

  const [columnVisibility, setColumnVisibility] = React.useState<VisibilityState>(() => {
    const vis: VisibilityState = {}
    columnDefinitions.forEach((col) => {
      if (col.visible === false || col.unshowable) vis[col.key] = false
    })
    if (persisted?.columnVisibility) Object.assign(vis, persisted.columnVisibility)
    // Unshowable columns can never be made visible, even via persisted state.
    columnDefinitions.forEach((col) => {
      if (col.unshowable) vis[col.key] = false
    })
    return vis
  })
  const [rowSelection, setRowSelection] = React.useState<RowSelectionState>(
    initialRowSelection || {}
  )
  const [globalFilter, setGlobalFilter] = React.useState(() => persisted?.globalFilter ?? "")
  const [columnSizing, setColumnSizing] = React.useState<ColumnSizingState>(
    () => persisted?.columnSizing ?? {}
  )
  const [columnOrder, setColumnOrder] = React.useState<ColumnOrderState>(
    () => persisted?.columnOrder ?? []
  )
  const [pagination, setPagination] = React.useState<PaginationState>(() => ({
    pageIndex: persisted?.pagination?.pageIndex ?? 0,
    pageSize: persisted?.pagination?.pageSize ?? (enablePagination ? pageSize : 999999),
  }))
  const [selectionViewMode, setSelectionViewMode] = React.useState<
    "all" | "selected" | "unselected"
  >("all")
  const [isImportPending, setIsImportPending] = React.useState(false)
  const [mounted, setMounted] = React.useState(false)
  React.useEffect(() => {
    setMounted(true)
  }, [])

  // Update data if initialData changes
  React.useEffect(() => {
    setData(initialData)
  }, [initialData])

  // Sync row selection if initialRowSelection changes externally
  React.useEffect(() => {
    if (initialRowSelection) {
      setRowSelection(initialRowSelection)
    }
  }, [initialRowSelection])

  React.useEffect(() => {
    if (importResult) {
      setIsImportPending(false)
    }
  }, [importResult])

  const handleColumnFiltersChange = React.useCallback(
    (updater: Updater<ColumnFiltersState>) => {
      setColumnFilters((prev) => {
        const next = typeof updater === "function" ? updater(prev) : updater

        for (const key of Object.keys(initialPredefinedFilters)) {
          if (touchedPredefinedFilterKeysRef.current.has(key)) continue

          const prevValue = String(prev.find((filter) => filter.id === key)?.value ?? "")
          const nextValue = String(next.find((filter) => filter.id === key)?.value ?? "")

          if (prevValue !== nextValue) {
            touchedPredefinedFilterKeysRef.current.add(key)
          }
        }

        return next
      })
    },
    [initialPredefinedFilters]
  )

  const activePredefinedFilterKeys = Object.keys(initialPredefinedFilters).filter(
    (key) => !touchedPredefinedFilterKeysRef.current.has(key)
  )

  // Parse row actions
  const rowActions = React.useMemo<TsTableRowAction[]>(() => {
    if (!singleItemActions) return []
    return singleItemActions.split(",").map((s) => {
      const parts = s.split("/")
      return { action: parts[0].trim(), label: parts[1]?.trim() || parts[0].trim() }
    })
  }, [singleItemActions])

  // Parse bulk actions
  const bulkActions = React.useMemo<TsTableRowAction[]>(() => {
    if (!multipleItemsActions) return []
    return multipleItemsActions.split(",").map((s) => {
      const parts = s.split("/")
      return { action: parts[0].trim(), label: parts[1]?.trim() || parts[0].trim() }
    })
  }, [multipleItemsActions])

  // Determine effective row actions based on enableRowMenu
  const effectiveRowActions = React.useMemo(
    () => (enableRowMenu ? rowActions : []),
    [enableRowMenu, rowActions]
  )

  // Determine click handlers based on enable flags
  const effectiveRowClick = enableClickableRows || enableClickableColumns ? onRowClick : undefined

  // Generate columns definition
  const columns = React.useMemo(
    () =>
      generateColumns<TData>(
        columnDefinitions,
        enableSelection,
        effectiveRowClick,
        effectiveRowActions,
        onAction,
        enableSorting,
        enableClickableColumns,
        enableColumnReordering,
        locale
      ),
    [
      columnDefinitions,
      enableSelection,
      effectiveRowClick,
      effectiveRowActions,
      onAction,
      enableSorting,
      enableClickableColumns,
      enableColumnReordering,
      locale,
    ]
  )

  const table = useReactTable({
    data,
    columns,
    state: {
      sorting,
      columnFilters,
      columnVisibility,
      rowSelection,
      globalFilter,
      columnSizing,
      columnOrder,
      pagination,
    },
    columnResizeMode: enableColumnResizing ? "onChange" : undefined,
    enableSorting,
    enableColumnFilters: enableFiltering,
    onSortingChange: setSorting,
    onColumnFiltersChange: handleColumnFiltersChange,
    onColumnVisibilityChange: setColumnVisibility,
    onRowSelectionChange: setRowSelection,
    onGlobalFilterChange: setGlobalFilter,
    onColumnSizingChange: setColumnSizing,
    onColumnOrderChange: setColumnOrder,
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: enablePagination ? getPaginationRowModel() : undefined,
    getSortedRowModel: enableSorting ? getSortedRowModel() : undefined,
    getRowId,
  })

  // Persist view state whenever it changes (no-op when persistStateKey is unset).
  React.useEffect(() => {
    savePersistedTableState(persistStateKey, {
      sorting,
      columnFilters,
      columnVisibility,
      columnSizing,
      columnOrder,
      globalFilter,
      pagination,
    })
  }, [
    persistStateKey,
    sorting,
    columnFilters,
    columnVisibility,
    columnSizing,
    columnOrder,
    globalFilter,
    pagination,
  ])

  // Propagate selection changes back up
  React.useEffect(() => {
    if (!onSelectionChange) return
    onSelectionChange(table.getFilteredSelectedRowModel().rows.map((row) => row.original))
  }, [onSelectionChange, table])

  // Get selected rows for toolbar
  const selectedRows = table.getFilteredSelectedRowModel().rows.map((row) => row.original)

  // Unshowable column keys for selector (#8: pass to toolbar for dimmed display)
  const unshowableColumnKeys = React.useMemo(
    () => columnDefinitions.filter((col) => col.unshowable).map((col) => col.key),
    [columnDefinitions]
  )

  return (
    <div className="relative w-full space-y-4" aria-busy={isImportPending}>
      <TsTableToolbar
        table={table}
        title={title}
        showFulltext={showFulltext}
        showCreateButton={showCreateButton}
        showImportButton={showImportButton}
        showExportButton={showExportButton}
        showColumnSelector={showColumnSelector}
        unhideableColumns={unhideableColumns}
        unshowableColumns={unshowableColumnKeys}
        bulkActions={bulkActions}
        selectedRows={selectedRows}
        onBulkAction={onBulkAction}
        onUnselectAll={() => setRowSelection({})}
        onCreateClick={onCreateClick}
        onImportStart={() => setIsImportPending(true)}
        onImportEnd={() => setIsImportPending(false)}
        onImportClick={onImport}
        onImportFile={onImportFile}
        columnDefinitions={columnDefinitions}
        columnsRequiredForImport={columnsRequiredForImport}
        predefinedFilterKeys={activePredefinedFilterKeys}
        locale={locale}
      />
      {isImportPending &&
        mounted &&
        createPortal(
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
            <div
              role="status"
              aria-live="polite"
              className="flex w-[400px] max-w-[90vw] flex-col items-center gap-3 rounded-lg border bg-background p-6 text-sm shadow-lg"
            >
              <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
              <div className="font-medium">{t.importWaiting}</div>
              <Button variant="outline" size="sm" onClick={() => setIsImportPending(false)}>
                {t.stopWaiting}
              </Button>
            </div>
          </div>,
          document.body
        )}
      <TsTableView
        table={table}
        enableFiltering={enableFiltering}
        enableColumnResizing={enableColumnResizing}
        enableColumnReordering={enableColumnReordering}
        selectionViewMode={selectionViewMode}
        onSelectionViewModeChange={setSelectionViewMode}
        hasSelectedRows={Object.keys(rowSelection).length > 0}
        onRowClick={enableClickableRows && onRowClick ? (row) => onRowClick(row) : undefined}
        bulkActions={bulkActions}
        selectedRowCount={selectedRows.length}
        onBulkAction={onBulkAction ? (action) => onBulkAction(action, selectedRows) : undefined}
        onUnselectAll={() => setRowSelection({})}
        locale={locale}
      />
      {/* Import results dialog — rendered via portal so it covers the full viewport */}
      {importResult &&
        mounted &&
        createPortal(
          <ImportResultDialog
            result={importResult}
            columnDefinitions={columnDefinitions}
            onClose={onImportResultClose ?? (() => {})}
            t={t}
          />,
          document.body
        )}
      {enablePagination && (
        <TsTablePagination table={table} pageSizeOptions={pageSizeOptions} locale={locale} />
      )}
    </div>
  )
}

"use client"

import { ColumnDef, Row } from "@tanstack/react-table"
import { ArrowDown, ArrowUp, ArrowUpDown, Check, ClipboardCopy, MoreVertical } from "lucide-react"

import * as React from "react"
import { TsLocale } from "@/components/ts-web-ui/locale"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Switch } from "@/components/ui/switch"

import { cn } from "@/lib/utils"

import { booleanFilter, dateFilter, numberFilter, textFilter } from "./filters"

function parseNumberCellValue(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) return value
  if (typeof value !== "string") return null

  const compact = value.trim().replace(/\s/g, "")
  if (!compact) return null

  const lastComma = compact.lastIndexOf(",")
  const lastDot = compact.lastIndexOf(".")
  let normalized = compact

  // If both separators are present, treat the right-most one as decimal separator.
  if (lastComma !== -1 && lastDot !== -1) {
    normalized =
      lastComma > lastDot ? compact.replace(/\./g, "").replace(",", ".") : compact.replace(/,/g, "")
  } else if (lastComma !== -1) {
    const parts = compact.split(",")
    if (parts.length === 2 && parts[1].length <= 2) {
      normalized = `${parts[0]}.${parts[1]}`
    } else {
      normalized = compact.replace(/,/g, "")
    }
  } else if (lastDot !== -1) {
    const parts = compact.split(".")
    if (!(parts.length === 2 && parts[1].length <= 2)) {
      normalized = compact.replace(/\./g, "")
    }
  }

  const parsed = Number(normalized)
  return Number.isFinite(parsed) ? parsed : null
}

function parseBooleanCellValue(value: unknown): boolean {
  if (typeof value === "boolean") return value
  if (typeof value === "number") return value !== 0
  if (typeof value === "string") {
    const normalized = value.trim().toLowerCase()
    // Includes common Czech localized values ("ano"/"ne") used by API payloads.
    if (["false", "0", "no", "n", "off", "ne", ""].includes(normalized)) return false
    if (["true", "1", "yes", "y", "on", "ano"].includes(normalized)) return true
  }
  return !!value
}

function CopyButton({ value, copyLabel }: { value: string; copyLabel?: string }) {
  const [copied, setCopied] = React.useState(false)
  const resetTimeoutRef = React.useRef<ReturnType<typeof setTimeout> | null>(null)
  const isMountedRef = React.useRef(false)

  React.useEffect(() => {
    isMountedRef.current = true
    return () => {
      isMountedRef.current = false
      if (resetTimeoutRef.current) {
        clearTimeout(resetTimeoutRef.current)
      }
    }
  }, [])

  const handleCopy = (e: React.MouseEvent) => {
    e.stopPropagation()
    navigator.clipboard.writeText(value).then(() => {
      if (!isMountedRef.current) return
      setCopied(true)
      if (resetTimeoutRef.current) {
        clearTimeout(resetTimeoutRef.current)
      }
      resetTimeoutRef.current = setTimeout(() => {
        if (isMountedRef.current) setCopied(false)
      }, 1500)
    })
  }

  return (
    <button
      type="button"
      className="inline-flex items-center justify-center h-6 w-6 rounded-sm hover:bg-accent shrink-0 opacity-0 group-hover/row:opacity-100 transition-opacity"
      onClick={handleCopy}
      aria-label={copyLabel ?? "Copy to clipboard"}
    >
      {copied ? (
        <Check className="h-4 w-4 text-green-500" />
      ) : (
        <ClipboardCopy className="h-4 w-4 text-foreground" />
      )}
    </button>
  )
}

export interface TsTableColumnDef {
  key: string
  title: string
  type?: "text" | "number" | "date" | "boolean"
  sortable?: boolean
  filterable?: boolean
  visible?: boolean
  unshowable?: boolean
  /** When true, the column's value is omitted from the Excel export. */
  excludeFromExport?: boolean
  width?: number | string
  align?: "left" | "center" | "right"
  canBeCopied?: boolean
  isClickable?: boolean
  locale?: string
  decimalPlaces?: number
}

export interface TsTableRowAction {
  action: string
  label: string
}

export function generateColumns<TData>(
  columnDefinitions: TsTableColumnDef[],
  enableSelection: boolean,
  onRowClick?: (row: TData, columnKey?: string) => void,
  rowActions?: TsTableRowAction[],
  onAction?: (action: string, row: TData) => void,
  enableSorting: boolean = true,
  enableClickableColumns: boolean = false,
  enableColumnReordering: boolean = true,
  tsLocale?: TsLocale
): ColumnDef<TData>[] {
  const t = tsLocale?.strings.table
  const cols: ColumnDef<TData>[] = []

  // 1. Selection column — header checkbox rendered in filter row by TsTableView
  if (enableSelection) {
    cols.push({
      id: "select",
      header: () => null,
      cell: ({ row }) => (
        <div className="flex justify-center">
          <input
            type="checkbox"
            checked={row.getIsSelected()}
            onChange={(e) => row.toggleSelected(e.target.checked)}
            aria-label={t?.selectRow ?? "Select row"}
            onClick={(e: React.MouseEvent) => e.stopPropagation()}
            className="h-4 w-4 accent-primary cursor-pointer"
          />
        </div>
      ),
      enableSorting: false,
      enableHiding: false,
      enableResizing: false,
      size: 40,
      minSize: 40,
      maxSize: 40,
    })
  }

  // 2. Row Actions Column (if enabled)
  if (rowActions && rowActions.length > 0) {
    cols.push({
      id: "actions",
      enableHiding: false,
      enableResizing: false,
      size: 40,
      minSize: 40,
      maxSize: 40,
      cell: ({ row }) => {
        return (
          <div className="flex justify-center" onClick={(e) => e.stopPropagation()}>
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="ghost" className="h-8 w-8 p-0">
                  <span className="sr-only">{t?.openMenu ?? "Open menu"}</span>
                  <MoreVertical className="h-4 w-4" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuLabel>{t?.actions ?? "Actions"}</DropdownMenuLabel>
                {rowActions.map((action, idx) => (
                  <DropdownMenuItem
                    key={idx}
                    onClick={() => onAction?.(action.action, row.original)}
                  >
                    {action.label}
                  </DropdownMenuItem>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        )
      },
    })
  }

  // 3. Data columns
  columnDefinitions.forEach((def) => {
    const locale = def.locale || "cs-CZ"
    const decimalPlaces = def.decimalPlaces ?? 2

    cols.push({
      accessorKey: def.key,
      header: ({ column }) => {
        const isSorted = column.getIsSorted()
        const isRight = def.align === "right"
        const isSortable = enableSorting && def.sortable !== false
        const sortIcon = isSortable ? (
          isSorted === "desc" ? (
            <ArrowDown className={cn("h-4 w-4 shrink-0", isRight ? "mr-1" : "ml-1")} />
          ) : isSorted === "asc" ? (
            <ArrowUp className={cn("h-4 w-4 shrink-0", isRight ? "mr-1" : "ml-1")} />
          ) : (
            <ArrowUpDown
              className={cn(
                "h-4 w-4 shrink-0 opacity-0 group-hover/header:opacity-50 transition-opacity",
                isRight ? "mr-1" : "ml-1"
              )}
            />
          )
        ) : null
        return (
          <Button
            variant="ghost"
            size="sm"
            className="h-8 data-[state=open]:bg-accent px-0 has-[>svg]:px-0 hover:bg-transparent hover:text-current dark:hover:bg-transparent"
            onClick={() => {
              if (!isSortable) return
              if (isSorted === "asc") {
                column.toggleSorting(true) // desc
              } else if (isSorted === "desc") {
                column.clearSorting() // no sort
              } else {
                column.toggleSorting(false) // asc
              }
            }}
            disabled={!isSortable}
          >
            {isRight && sortIcon}
            <span className="truncate">{def.title}</span>
            {!isRight && sortIcon}
          </Button>
        )
      },
      cell: ({ row }) => {
        const value = row.getValue(def.key)

        let formattedValue: React.ReactNode = String(value ?? "")

        if (def.type === "number") {
          const numericValue = parseNumberCellValue(value)
          if (numericValue !== null) {
            formattedValue = numericValue.toLocaleString(locale, {
              minimumFractionDigits: decimalPlaces,
              maximumFractionDigits: decimalPlaces,
            })
          }
        } else if (def.type === "date" && value) {
          const d = new Date(value as string)
          if (!isNaN(d.getTime())) {
            formattedValue = new Intl.DateTimeFormat(locale).format(d)
          }
        } else if (def.type === "boolean") {
          formattedValue = (
            <div
              className={cn(
                "flex",
                def.align === "center" && "justify-center",
                def.align === "right" && "justify-end"
              )}
            >
              <Switch
                checked={parseBooleanCellValue(value)}
                aria-readonly="true"
                tabIndex={-1}
                className="pointer-events-none"
              />
            </div>
          )
        }

        return (
          <div
            className={cn(
              "flex items-center gap-1",
              def.align === "center" && "justify-center",
              def.align === "right" && "justify-end",
              enableClickableColumns &&
                def.isClickable &&
                "text-primary hover:underline cursor-pointer font-medium"
            )}
            onClick={(e) => {
              if (enableClickableColumns && def.isClickable) {
                e.stopPropagation()
                onRowClick?.(row.original, def.key)
              }
            }}
          >
            <span className="truncate">{formattedValue}</span>
            {def.canBeCopied && value != null && (
              <CopyButton value={String(value)} copyLabel={t?.copyToClipboard} />
            )}
          </div>
        )
      },
      enableSorting: enableSorting && (def.sortable ?? true),
      ...((!def.type || def.type === "text") && enableSorting && def.sortable !== false
        ? {
            sortingFn: (rowA: Row<TData>, rowB: Row<TData>, columnId: string) => {
              const a = String(rowA.getValue(columnId) ?? "")
              const b = String(rowB.getValue(columnId) ?? "")
              return a.localeCompare(b, locale)
            },
          }
        : {}),
      enableColumnFilter: def.filterable ?? true,
      size: typeof def.width === "number" ? def.width : 200,
      minSize: (() => {
        const isSortable = enableSorting && def.sortable !== false
        // ~8.5px per character at text-sm (slightly over-estimate to avoid truncation)
        const labelPx = Math.ceil(def.title.length * 8.5)
        // Sort icon: 16px icon + 6px gap = 22px
        const sortPx = isSortable ? 22 : 0
        // Reorder arrows: 2 x (12px icon + 5px padding) + 2px gap = 36px
        const reorderPx = enableColumnReordering ? 36 : 0
        // Cell padding: px-3 both sides = 24px
        const paddingPx = 24
        return Math.max(labelPx + sortPx + reorderPx + paddingPx, 60)
      })(),
      filterFn: (row, id, value, addMeta) => {
        // biome-ignore lint/suspicious/noExplicitAny: TanStack Table filterFn requires row type cast
        if (def.type === "number") return numberFilter(row as any, id, value, addMeta)
        // biome-ignore lint/suspicious/noExplicitAny: TanStack Table filterFn requires row type cast
        if (def.type === "date") return dateFilter(row as any, id, value, addMeta)
        // biome-ignore lint/suspicious/noExplicitAny: TanStack Table filterFn requires row type cast
        if (def.type === "boolean") return booleanFilter(row as any, id, value, addMeta)
        // biome-ignore lint/suspicious/noExplicitAny: TanStack Table filterFn requires row type cast
        return textFilter(row as any, id, value, addMeta)
      },
      meta: {
        title: def.title,
        type: def.type,
        align: def.align,
      },
    })
  })

  return cols
}

import { FilterFn } from "@tanstack/react-table"

const EMPTY_FILTER_VALUE = "!*"

function isEmptyFilterValue(filterValue: unknown): boolean {
  return String(filterValue).trim() === EMPTY_FILTER_VALUE
}

function isEmptyCellValue(value: unknown): boolean {
  return value == null || (typeof value === "string" && value.trim() === "")
}

/**
 * Match text with wildcard support: * (any chars), ? (single char).
 * Falls back to case-insensitive substring match if no wildcards present.
 */
export function matchTextPattern(text: string, pattern: string): boolean {
  const lowText = text.toLowerCase()
  const lowPattern = pattern.toLowerCase()

  // If no wildcards, use simple substring match
  if (!lowPattern.includes("*") && !lowPattern.includes("?")) {
    return lowText.includes(lowPattern)
  }

  // Convert wildcard pattern to regex: * → .*, ? → .
  const escaped = lowPattern.replace(/[.+^${}()|[\]\\]/g, "\\$&")
  const regexStr = "^" + escaped.replace(/\*/g, ".*").replace(/\?/g, ".") + "$"
  try {
    return new RegExp(regexStr).test(lowText)
  } catch {
    return lowText.includes(lowPattern)
  }
}

// ---- Number Filter (matches reference implementation) ----

function parseNumberRange(filterValue: string): { min: number | null; max: number | null } | null {
  const trimmed = filterValue.trim()
  if (!trimmed) return null

  // Range with ".." separator: "10..20", "..20", "10.."
  if (trimmed.includes("..")) {
    const parts = trimmed.split("..")
    const minStr = parts[0]?.trim()
    const maxStr = parts[1]?.trim()
    return {
      min: minStr ? (isNaN(parseFloat(minStr)) ? null : parseFloat(minStr)) : null,
      max: maxStr ? (isNaN(parseFloat(maxStr)) ? null : parseFloat(maxStr)) : null,
    }
  }

  // Single number — exact match (text startsWith)
  const parsed = parseFloat(trimmed)
  if (!isNaN(parsed)) {
    return { min: parsed, max: parsed }
  }

  return null
}

export const numberFilter: FilterFn<unknown> = (row, columnId, filterValue) => {
  const cellValue = row.getValue(columnId) as number
  if (isEmptyFilterValue(filterValue)) return isEmptyCellValue(cellValue)
  if (typeof cellValue !== "number") return false

  const range = parseNumberRange(String(filterValue))
  if (!range) {
    // Fallback to text matching
    return matchTextPattern(String(cellValue), String(filterValue))
  }

  if (range.min !== null && range.max !== null && range.min === range.max) {
    // Exact number — match if cell equals or cell string starts with filter
    return cellValue === range.min || String(cellValue).startsWith(String(filterValue).trim())
  }

  if (range.min !== null && cellValue < range.min) return false
  if (range.max !== null && cellValue > range.max) return false
  return true
}

// ---- Date Filter (matches reference implementation: flexible date parsing) ----

function parseFlexibleDate(dateStr: string): Date | null {
  if (!dateStr) return null
  const s = dateStr.trim()

  // DD.MM.YYYY (Czech format)
  const m1 = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/)
  if (m1) {
    const d = new Date(Number(m1[3]), Number(m1[2]) - 1, Number(m1[1]))
    if (!isNaN(d.getTime())) return d
  }

  // DD.MM.YY
  const m2 = s.match(/^(\d{1,2})\.(\d{1,2})\.(\d{2})$/)
  if (m2) {
    const yr = Number(m2[3])
    const fullYear = yr < 50 ? 2000 + yr : 1900 + yr
    const d = new Date(fullYear, Number(m2[2]) - 1, Number(m2[1]))
    if (!isNaN(d.getTime())) return d
  }

  // ISO YYYY-MM-DD (parse as local, not UTC)
  const m3 = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/)
  if (m3) {
    const d = new Date(Number(m3[1]), Number(m3[2]) - 1, Number(m3[3]))
    if (!isNaN(d.getTime())) return d
  }

  // Year only YYYY
  const m4 = s.match(/^(\d{4})$/)
  if (m4) {
    return new Date(Number(m4[1]), 0, 1)
  }

  // Month.Year DD.MM or MM.YYYY
  const m5 = s.match(/^(\d{1,2})\.(\d{4})$/)
  if (m5) {
    return new Date(Number(m5[2]), Number(m5[1]) - 1, 1)
  }

  return null
}

function setEndOfPeriod(date: Date, input: string): Date {
  const s = input.trim()
  const d = new Date(date)

  // If only year was entered, end of year
  if (/^\d{4}$/.test(s)) {
    d.setMonth(11, 31)
    d.setHours(23, 59, 59, 999)
    return d
  }

  // If month.year, end of month
  if (/^\d{1,2}\.\d{4}$/.test(s)) {
    d.setMonth(d.getMonth() + 1, 0) // last day of month
    d.setHours(23, 59, 59, 999)
    return d
  }

  // Otherwise end of day
  d.setHours(23, 59, 59, 999)
  return d
}

export const dateFilter: FilterFn<unknown> = (row, columnId, filterValue) => {
  const cellValue = row.getValue(columnId)
  if (isEmptyFilterValue(filterValue)) return isEmptyCellValue(cellValue)
  if (!cellValue) return false

  const cellDate = new Date(cellValue as string)
  if (isNaN(cellDate.getTime())) return false
  const normalizedCellDate = new Date(
    cellDate.getFullYear(),
    cellDate.getMonth(),
    cellDate.getDate()
  )

  const val = String(filterValue).trim()
  if (!val) return true

  // Range with ".."
  if (val.includes("..")) {
    const [startStr, endStr] = val.split("..")
    const min = startStr?.trim() ? parseFlexibleDate(startStr.trim()) : null
    const max = endStr?.trim() ? parseFlexibleDate(endStr.trim()) : null
    const maxEnd = max && endStr?.trim() ? setEndOfPeriod(max, endStr.trim()) : null

    if (min && normalizedCellDate < min) return false
    if (maxEnd && normalizedCellDate > maxEnd) return false
    return true
  }

  // Single date/period
  const parsed = parseFlexibleDate(val)
  if (parsed) {
    const end = setEndOfPeriod(new Date(parsed), val)
    return normalizedCellDate >= parsed && normalizedCellDate <= end
  }

  // Fallback: text match on formatted date (cs-CZ)
  const formatted = new Intl.DateTimeFormat("cs-CZ").format(normalizedCellDate)
  return matchTextPattern(formatted, val)
}

// ---- Boolean Filter ----

export const booleanFilter: FilterFn<unknown> = (row, columnId, filterValue) => {
  const cellValue = row.getValue(columnId)
  if (isEmptyFilterValue(filterValue)) return isEmptyCellValue(cellValue)
  // Accept both boolean values (from predefinedFilters) and string values (from UI)
  if (filterValue === true || filterValue === "true") return cellValue === true
  if (filterValue === false || filterValue === "false") return cellValue === false
  return true // 'all' or empty
}

// ---- Text Filter ----

export const textFilter: FilterFn<unknown> = (row, columnId, filterValue) => {
  const cellValue = row.getValue(columnId)
  if (isEmptyFilterValue(filterValue)) return isEmptyCellValue(cellValue)
  if (cellValue == null) return false
  return matchTextPattern(String(cellValue), String(filterValue))
}

import type {
  ColumnFiltersState,
  ColumnOrderState,
  ColumnSizingState,
  PaginationState,
  SortingState,
  VisibilityState,
} from "@tanstack/react-table"

/**
 * Snapshot of the user-controllable TsTable view state that can be persisted across navigation.
 */
export interface PersistedTableState {
  sorting?: SortingState
  columnFilters?: ColumnFiltersState
  columnVisibility?: VisibilityState
  columnSizing?: ColumnSizingState
  columnOrder?: ColumnOrderState
  globalFilter?: string
  pagination?: PaginationState
}

const STORAGE_PREFIX = "tswebui:ts-table:"

function getStorage(): Storage | null {
  try {
    if (typeof window === "undefined") return null
    return window.localStorage
  } catch {
    // Accessing localStorage can throw (e.g. disabled cookies / privacy mode).
    return null
  }
}

/**
 * Read a previously persisted table state for the given key. Returns null when no key is
 * provided, storage is unavailable, or the stored value is missing/corrupt.
 */
export function loadPersistedTableState(key?: string): PersistedTableState | null {
  if (!key) return null
  const storage = getStorage()
  if (!storage) return null
  try {
    const raw = storage.getItem(`${STORAGE_PREFIX}${key}`)
    if (!raw) return null
    const parsed = JSON.parse(raw) as PersistedTableState
    return parsed && typeof parsed === "object" ? parsed : null
  } catch {
    return null
  }
}

/**
 * Persist the table state for the given key. No-op when no key is provided or storage is
 * unavailable.
 */
export function savePersistedTableState(key: string | undefined, state: PersistedTableState): void {
  if (!key) return
  const storage = getStorage()
  if (!storage) return
  try {
    storage.setItem(`${STORAGE_PREFIX}${key}`, JSON.stringify(state))
  } catch {
    // Quota / serialization errors are non-fatal for a view-state cache.
  }
}

"use client"

import { Table } from "@tanstack/react-table"
import { Download, Filter, Plus, Search, Settings2, Upload, XCircle } from "lucide-react"
import * as React from "react"
import { toast } from "sonner"
import * as XLSX from "xlsx"
import { TsLocale } from "@/components/ts-web-ui/locale"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"

import { cn } from "@/lib/utils"

import { TsTableColumnDef, TsTableRowAction } from "./columns"

interface TsTableToolbarProps<TData> {
  table: Table<TData>
  showFulltext?: boolean
  showCreateButton?: boolean
  showImportButton?: boolean
  showExportButton?: boolean
  showColumnSelector?: boolean
  unhideableColumns?: string[]
  unshowableColumns?: string[]
  bulkActions?: TsTableRowAction[]
  selectedRows?: TData[]
  onBulkAction?: (action: string, rows: TData[]) => void
  onUnselectAll?: () => void
  onCreateClick?: () => void
  onImportStart?: () => void
  onImportEnd?: () => void
  onImportClick?: (data: Record<string, unknown>[]) => void
  /**
   * When provided, the raw selected File is handed to this callback and the built-in XLSX
   * parsing/column-filtering is skipped — the consumer is responsible for parsing it
   * (e.g. read as UTF-8, keep cells as strings, keep all columns). Takes precedence over
   * onImportClick.
   */
  onImportFile?: (file: File) => void | Promise<void>
  columnDefinitions?: TsTableColumnDef[]
  columnsRequiredForImport?: string[]
  predefinedFilterKeys?: string[]
  title?: string
  locale?: TsLocale
}

export function TsTableToolbar<TData>({
  table,
  showFulltext = true,
  showCreateButton = true,
  showImportButton = true,
  showExportButton = true,
  showColumnSelector = true,
  unhideableColumns = [],
  unshowableColumns = [],
  bulkActions: _bulkActions = [],
  selectedRows = [],
  onBulkAction: _onBulkAction,
  onUnselectAll: _onUnselectAll,
  onCreateClick,
  onImportStart,
  onImportEnd,
  onImportClick,
  onImportFile,
  columnDefinitions = [],
  columnsRequiredForImport,
  predefinedFilterKeys = [],
  title,
  locale,
}: TsTableToolbarProps<TData>) {
  const t = locale?.strings.table
  const [columnSearch, setColumnSearch] = React.useState("")
  const [columnDropdownOpen, setColumnDropdownOpen] = React.useState(false)

  const getColumnLabel = React.useCallback(
    (column: ReturnType<Table<TData>["getAllLeafColumns"]>[number]) => {
      const meta = column.columnDef.meta as { title?: string } | undefined
      if (typeof meta?.title === "string" && meta.title.trim()) {
        return meta.title
      }

      const definitionTitle = columnDefinitions.find(
        (definition) => definition.key === column.id
      )?.title
      if (definitionTitle) {
        return definitionTitle
      }

      const header = column.columnDef.header
      return typeof header === "string" ? header : column.id
    },
    [columnDefinitions]
  )

  const doExport = (rows: TData[]) => {
    // Columns flagged excludeFromExport are stripped from each exported row.
    const excludedKeys = columnDefinitions
      .filter((definition) => definition.excludeFromExport)
      .map((definition) => definition.key)
    const exportRows =
      excludedKeys.length === 0
        ? rows
        : rows.map((row) => {
            const clone = { ...(row as Record<string, unknown>) }
            for (const key of excludedKeys) {
              delete clone[key]
            }
            return clone as TData
          })
    const ws = XLSX.utils.json_to_sheet(exportRows)
    const wb = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(wb, ws, "Data")
    XLSX.writeFile(wb, `export-${new Date().toISOString().split("T")[0]}.xlsx`)
  }

  const handleExportAll = () => {
    doExport(table.getCoreRowModel().rows.map((row) => row.original))
  }

  const handleExportFiltered = () => {
    doExport(table.getFilteredRowModel().rows.map((row) => row.original))
  }

  const handleExportSelected = () => {
    doExport(selectedRows)
  }

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    onImportStart?.()

    // Open pipeline: hand the raw file to the consumer and skip built-in parsing/filtering.
    if (onImportFile) {
      void onImportFile(file)
      e.target.value = ""
      return
    }

    const reader = new FileReader()
    reader.onload = (event) => {
      const data = event.target?.result
      if (!data) return
      const wb = XLSX.read(data, { type: "array" })
      const wsname = wb.SheetNames[0]
      const ws = wb.Sheets[wsname]
      const json = XLSX.utils.sheet_to_json(ws, { defval: "" }) as Record<string, unknown>[]

      // Empty file — nothing to import
      if (json.length === 0) {
        toast.info(t?.importNoData ?? "Import file contains no data rows")
        onImportEnd?.()
        return
      }

      // Validate column headers
      const headersInFile = Object.keys(json[0] || {})
      const columnsToValidate =
        columnsRequiredForImport && columnsRequiredForImport.length > 0
          ? columnDefinitions.filter((col) => columnsRequiredForImport.includes(col.key))
          : columnDefinitions
      const missingColumns = columnsToValidate
        .map((col) => col.key)
        .filter((key) => !headersInFile.includes(key))

      if (missingColumns.length > 0) {
        const label =
          columnsRequiredForImport && columnsRequiredForImport.length > 0
            ? (t?.missingRequiredColumns ?? "Missing required columns")
            : (t?.missingColumns ?? "Missing columns")
        toast.error(t?.importFailedMissing?.(label) ?? `Import failed: ${label}`, {
          description: missingColumns.join(", "),
        })
        onImportEnd?.()
        return
      }

      // Map rows: keep only known keys from column definitions
      const knownKeys = new Set(columnDefinitions.map((c) => c.key))
      const mapped = json.map((row) => {
        const obj: Record<string, unknown> = {}
        for (const [key, val] of Object.entries(row)) {
          if (knownKeys.has(key)) obj[key] = val
        }
        return obj
      })

      // Call external handler — parent is responsible for processing and showing results
      if (onImportClick) {
        onImportClick(mapped)
      } else {
        onImportEnd?.()
      }
    }
    reader.readAsArrayBuffer(file)

    // Reset input so the same file can be re-imported
    e.target.value = ""
  }

  // Get columns in the order they are displayed (#1: react to column order/visibility changes)
  const columnOrderState = table.getState().columnOrder
  const orderedColumns = (() => {
    const allColumns = table.getAllLeafColumns()
    const allCols = allColumns.filter((c) => c.id !== "select" && c.id !== "actions")

    // Sort all columns by their position in the current column order
    // Hidden columns stay in their original position among visible ones
    const orderMap = new Map<string, number>()
    if (columnOrderState.length > 0) {
      columnOrderState.forEach((id, idx) => orderMap.set(id, idx))
    } else {
      allColumns.forEach((col, idx) => orderMap.set(col.id, idx))
    }
    return [...allCols].sort((a, b) => {
      return (orderMap.get(a.id) ?? 999) - (orderMap.get(b.id) ?? 999)
    })
  })()

  // Check for active column filters (#9)
  const columnFiltersState = table.getState().columnFilters
  const activeFilterIds = React.useMemo(() => {
    return new Set(
      columnFiltersState.filter((f) => f.value !== "" && f.value != null).map((f) => f.id)
    )
  }, [columnFiltersState])
  const hasActiveUserFilters = React.useMemo(() => {
    return columnFiltersState.some(
      (f) => f.value !== "" && f.value != null && !predefinedFilterKeys.includes(f.id)
    )
  }, [columnFiltersState, predefinedFilterKeys])

  const globalFilterState = table.getState().globalFilter as string | undefined
  const hasAnyActiveFilter =
    columnFiltersState.some((f) => f.value !== "" && f.value != null) || !!globalFilterState

  const handleClearAllFilters = React.useCallback(() => {
    const predefinedOnly = table
      .getState()
      .columnFilters.filter((f) => predefinedFilterKeys.includes(f.id))
    table.setColumnFilters(predefinedOnly)
  }, [table, predefinedFilterKeys])

  return (
    <div className="space-y-4 pt-4 pb-0">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex-1 min-w-0">
          {title && <h2 className="text-lg font-semibold">{title}</h2>}
        </div>

        <div className="flex items-center gap-2">
          {showColumnSelector && (
            <DropdownMenu
              open={columnDropdownOpen}
              onOpenChange={(open) => {
                setColumnDropdownOpen(open)
                if (!open) setColumnSearch("")
              }}
            >
              <DropdownMenuTrigger asChild>
                <Button variant="outline" size="sm" className="h-9 ml-auto flex gap-2">
                  <Settings2 className="h-4 w-4" />
                  {t?.columns ?? "Columns"}
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent
                align="end"
                className="w-[220px]"
                onEscapeKeyDown={(e) => {
                  // If search is active, first Escape clears search; only then closes dropdown
                  if (columnSearch) {
                    e.preventDefault()
                    setColumnSearch("")
                  }
                }}
              >
                <DropdownMenuLabel>{t?.viewColumns ?? "View columns"}</DropdownMenuLabel>
                <DropdownMenuSeparator />
                {/* Clear all filters (#9) */}
                {hasActiveUserFilters && (
                  <>
                    <DropdownMenuItem
                      className="text-destructive focus:text-destructive"
                      onClick={handleClearAllFilters}
                      onSelect={(e) => e.preventDefault()}
                    >
                      <XCircle className="h-3.5 w-3.5 mr-1.5" />
                      {t?.clearAllFilters ?? "Clear all filters"}
                    </DropdownMenuItem>
                    <DropdownMenuSeparator />
                  </>
                )}
                <div
                  className="px-2 pb-1.5"
                  onPointerDown={(e) => {
                    // Prevent dropdown from stealing focus when clicking inside the search area
                    e.stopPropagation()
                  }}
                >
                  <Input
                    placeholder={t?.searchColumns ?? "Search columns..."}
                    value={columnSearch}
                    onChange={(e) => setColumnSearch(e.target.value)}
                    onKeyDown={(e) => {
                      // Stop key events from reaching dropdown (prevents typeahead focus stealing)
                      // Escape is handled by DropdownMenuContent.onEscapeKeyDown
                      e.stopPropagation()
                      if (e.key === "Enter") e.preventDefault()
                    }}
                    onBlur={(e) => {
                      // If focus moved within the dropdown content, reclaim it
                      const container = (e.target as HTMLElement).closest('[role="menu"]')
                      if (container?.contains(e.relatedTarget as Node)) {
                        e.target.focus()
                      }
                    }}
                    className="h-7 text-xs"
                    autoFocus
                  />
                </div>
                <div className="max-h-[300px] overflow-y-auto">
                  {orderedColumns
                    .filter((column) => {
                      if (!columnSearch) return true
                      const label = getColumnLabel(column)
                      return label.toLowerCase().includes(columnSearch.toLowerCase())
                    })
                    .map((column) => {
                      const isUnhideable = unhideableColumns.includes(column.id)
                      const isUnshowable = unshowableColumns.includes(column.id)
                      const label = getColumnLabel(column)
                      const hasFilter = activeFilterIds.has(column.id)
                      return (
                        <DropdownMenuCheckboxItem
                          key={column.id}
                          className={cn(isUnshowable && "opacity-50")}
                          checked={column.getIsVisible()}
                          disabled={isUnhideable || isUnshowable}
                          onCheckedChange={(value) => {
                            if (!isUnhideable && !isUnshowable) column.toggleVisibility(!!value)
                          }}
                          onSelect={(e) => e.preventDefault()}
                        >
                          <span className="flex items-center w-full">
                            <span className="flex-1 truncate">{label}</span>
                            {hasFilter && (
                              <Filter className="h-3 w-3 text-primary shrink-0 ml-auto" />
                            )}
                          </span>
                        </DropdownMenuCheckboxItem>
                      )
                    })}
                </div>
              </DropdownMenuContent>
            </DropdownMenu>
          )}

          {showExportButton && !hasAnyActiveFilter && selectedRows.length === 0 && (
            <Button variant="outline" size="sm" className="h-9 gap-2" onClick={handleExportAll}>
              <Download className="h-4 w-4" />
              {t?.export ?? "Export"}
            </Button>
          )}

          {showExportButton &&
            (hasAnyActiveFilter || selectedRows.length > 0) &&
            (() => {
              const allCount = table.getCoreRowModel().rows.length
              const filteredCount = table.getFilteredRowModel().rows.length
              const selectedCount = selectedRows.length
              return (
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <Button variant="outline" size="sm" className="h-9 gap-2">
                      <Download className="h-4 w-4" />
                      {t?.export ?? "Export"}
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end">
                    <DropdownMenuItem onClick={handleExportAll}>
                      {t?.exportAll?.(allCount) ?? `Export all (${allCount} rows)`}
                    </DropdownMenuItem>
                    {selectedCount > 0 && (
                      <DropdownMenuItem onClick={handleExportSelected}>
                        {t?.exportSelected?.(selectedCount) ??
                          `Export selected (${selectedCount} rows)`}
                      </DropdownMenuItem>
                    )}
                    {hasAnyActiveFilter && (
                      <DropdownMenuItem
                        onClick={handleExportFiltered}
                        disabled={filteredCount === 0}
                      >
                        {t?.exportFiltered?.(filteredCount) ??
                          `Export filtered (${filteredCount} rows)`}
                      </DropdownMenuItem>
                    )}
                  </DropdownMenuContent>
                </DropdownMenu>
              )
            })()}

          {showImportButton && (
            <div className="relative">
              <Button variant="outline" size="sm" className="h-9 gap-2" asChild>
                <label className="cursor-pointer">
                  <Upload className="h-4 w-4" />
                  {t?.import ?? "Import"}
                  <input
                    type="file"
                    className="hidden"
                    accept=".xlsx,.xls,.csv,.json"
                    onChange={handleImport}
                  />
                </label>
              </Button>
            </div>
          )}

          {showCreateButton && (
            <Button size="sm" className="h-9 gap-2" onClick={onCreateClick}>
              <Plus className="h-4 w-4" />
              {t?.newRecord ?? "New record"}
            </Button>
          )}
        </div>
      </div>

      {showFulltext && (
        <div className="relative w-full">
          <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder={t?.search ?? "Search..."}
            value={(table.getState().globalFilter as string) ?? ""}
            onChange={(event) => table.setGlobalFilter(event.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                e.preventDefault()
                table.setGlobalFilter("")
              }
            }}
            className="pl-8 h-9"
          />
        </div>
      )}
    </div>
  )
}

"use client"

import { flexRender, Table as TanStackTable } from "@tanstack/react-table"
import { Check, ChevronLeft, ChevronRight, Filter, MoreVertical, X as XIcon } from "lucide-react"

import * as React from "react"
import { TsLocale } from "@/components/ts-web-ui/locale"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"

import { cn } from "@/lib/utils"

import { TsTableRowAction } from "./columns"

const FILTER_DEBOUNCE_DELAY = 500

function DebouncedFilterInput({
  value: externalValue,
  onChange,
  ...props
}: {
  value: string
  onChange: (value: string) => void
} & Omit<React.ComponentProps<typeof Input>, "value" | "onChange">) {
  const [localValue, setLocalValue] = React.useState(externalValue)
  const timeoutRef = React.useRef<ReturnType<typeof setTimeout> | undefined>(undefined)

  // Sync from external if changed programmatically
  React.useEffect(() => {
    setLocalValue(externalValue)
  }, [externalValue])

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newValue = e.target.value
    setLocalValue(newValue)
    if (timeoutRef.current) clearTimeout(timeoutRef.current)
    timeoutRef.current = setTimeout(() => onChange(newValue), FILTER_DEBOUNCE_DELAY)
  }

  React.useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current)
    }
  }, [])

  return (
    <Input
      {...props}
      value={localValue}
      onChange={handleChange}
      onKeyDown={(e) => {
        if (e.key === "Escape") {
          e.preventDefault()
          setLocalValue("")
          if (timeoutRef.current) clearTimeout(timeoutRef.current)
          onChange("")
        }
      }}
    />
  )
}

export type SelectionViewMode = "all" | "selected" | "unselected"

interface TsTableViewProps<TData> {
  table: TanStackTable<TData>
  enableFiltering?: boolean
  enableColumnResizing?: boolean
  enableColumnReordering?: boolean
  selectionViewMode?: SelectionViewMode
  onSelectionViewModeChange?: (mode: SelectionViewMode) => void
  hasSelectedRows?: boolean
  onRowClick?: (row: TData) => void
  bulkActions?: TsTableRowAction[]
  selectedRowCount?: number
  onBulkAction?: (action: string) => void
  onUnselectAll?: () => void
  locale?: TsLocale
}

export function TsTableView<TData>({
  table,
  enableFiltering = true,
  enableColumnResizing = true,
  enableColumnReordering = true,
  selectionViewMode = "all",
  onSelectionViewModeChange,
  hasSelectedRows = false,
  onRowClick,
  bulkActions = [],
  selectedRowCount = 0,
  onBulkAction,
  onUnselectAll,
  locale,
}: TsTableViewProps<TData>) {
  const t = locale?.strings.table
  const cycleSelectionView = React.useCallback(() => {
    const modes: SelectionViewMode[] = ["all", "selected", "unselected"]
    const currentIdx = modes.indexOf(selectionViewMode)
    const nextIdx = (currentIdx + 1) % modes.length
    onSelectionViewModeChange?.(modes[nextIdx])
  }, [selectionViewMode, onSelectionViewModeChange])

  const handleMoveColumn = React.useCallback(
    (columnId: string, direction: "left" | "right") => {
      const currentOrder = table.getState().columnOrder
      const allColumnIds =
        currentOrder.length > 0 ? [...currentOrder] : table.getAllLeafColumns().map((c) => c.id)

      // Find movable range: skip "select" and "actions" at the beginning
      const fixedPrefixCount = allColumnIds.filter(
        (id) => id === "select" || id === "actions"
      ).length
      const movableIds = allColumnIds.slice(fixedPrefixCount)

      const idx = movableIds.indexOf(columnId)
      if (idx < 0) return

      const swapIdx = direction === "left" ? idx - 1 : idx + 1
      if (swapIdx < 0 || swapIdx >= movableIds.length) return

      // Swap in movable range
      const temp = movableIds[idx]
      movableIds[idx] = movableIds[swapIdx]
      movableIds[swapIdx] = temp

      const newOrder = [...allColumnIds.slice(0, fixedPrefixCount), ...movableIds]
      table.setColumnOrder(newOrder)
    },
    [table]
  )

  // Get visible data columns for checking move boundaries (#5: react to column order)
  const visibleDataColumns = table
    .getVisibleLeafColumns()
    .filter((c) => c.id !== "select" && c.id !== "actions")

  // Measure container width so we can distribute extra space only to data columns
  const containerRef = React.useRef<HTMLDivElement>(null)

  // Compute effective column widths: fixed always 40px, data columns use their natural size
  const FIXED_COL_PX = 40
  const columnWidthMap = (() => {
    const cols = table.getVisibleLeafColumns()
    const map = new Map<string, number>()

    for (const col of cols) {
      const isFixed = col.id === "select" || col.id === "actions"
      map.set(col.id, isFixed ? FIXED_COL_PX : col.getSize())
    }

    return map
  })()

  const effectiveTableWidth = React.useMemo(() => {
    let sum = 0
    for (const w of columnWidthMap.values()) sum += w
    return sum
  }, [columnWidthMap])

  return (
    <div ref={containerRef} className="rounded-md border bg-card overflow-x-auto">
      <Table
        style={{
          width: effectiveTableWidth || table.getCenterTotalSize(),
          tableLayout: "fixed",
        }}
      >
        {/* Colgroup for column widths */}
        <colgroup>
          {table.getVisibleLeafColumns().map((col) => (
            <col key={col.id} style={{ width: columnWidthMap.get(col.id) ?? col.getSize() }} />
          ))}
        </colgroup>
        <TableHeader className="bg-muted/50">
          {table.getHeaderGroups().map((headerGroup) => (
            <React.Fragment key={headerGroup.id}>
              {/* Row 1: Header labels + reorder buttons + select-all */}
              <TableRow>
                {headerGroup.headers.map((header) => {
                  const isDataColumn =
                    header.column.id !== "select" && header.column.id !== "actions"
                  const isFirstData = isDataColumn && visibleDataColumns[0]?.id === header.column.id
                  const isLastData =
                    isDataColumn &&
                    visibleDataColumns[visibleDataColumns.length - 1]?.id === header.column.id
                  const meta = header.column.columnDef.meta as
                    | { type?: string; align?: string }
                    | undefined
                  const colAlign = (isDataColumn && meta?.align) || "left"

                  return (
                    <TableHead
                      key={header.id}
                      className={cn(
                        "py-2 px-3 font-bold text-muted-foreground relative group/header",
                        !isDataColumn && "w-[40px] min-w-[40px] max-w-[40px] p-0"
                      )}
                      style={{
                        width: columnWidthMap.get(header.column.id) ?? header.getSize(),
                        ...(isDataColumn && enableColumnResizing
                          ? { minWidth: header.column.columnDef.minSize ?? 60 }
                          : {}),
                      }}
                    >
                      {/* Select-all checkbox + selection filter in row 1 (#4) */}
                      {header.column.id === "select" ? (
                        <div className="h-8 flex items-center justify-center gap-1">
                          <input
                            type="checkbox"
                            checked={table.getIsAllPageRowsSelected()}
                            ref={(el) => {
                              if (el) {
                                el.indeterminate =
                                  table.getIsSomePageRowsSelected() &&
                                  !table.getIsAllPageRowsSelected()
                              }
                            }}
                            onChange={(e) => table.toggleAllPageRowsSelected(e.target.checked)}
                            aria-label={t?.selectAll ?? "Select all"}
                            className="h-4 w-4 accent-primary cursor-pointer"
                          />
                        </div>
                      ) : header.column.id === "actions" ? (
                        // Bulk actions menu (#11)
                        selectedRowCount > 0 && bulkActions.length > 0 ? (
                          <div className="flex justify-center">
                            <DropdownMenu>
                              <DropdownMenuTrigger asChild>
                                <Button variant="ghost" className="h-7 w-7 p-0">
                                  <span className="sr-only">
                                    {t?.bulkActions ?? "Bulk actions"}
                                  </span>
                                  <MoreVertical className="h-4 w-4" />
                                </Button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end">
                                <DropdownMenuLabel>
                                  {t?.selected?.(selectedRowCount) ??
                                    `Selected: ${selectedRowCount}`}
                                </DropdownMenuLabel>
                                <DropdownMenuSeparator />
                                <DropdownMenuItem onClick={() => onUnselectAll?.()}>
                                  {t?.unselectAll ?? "Unselect all"}
                                </DropdownMenuItem>
                                {bulkActions.map((action, idx) => (
                                  <DropdownMenuItem
                                    key={idx}
                                    onClick={() => onBulkAction?.(action.action)}
                                  >
                                    {action.label}
                                  </DropdownMenuItem>
                                ))}
                              </DropdownMenuContent>
                            </DropdownMenu>
                          </div>
                        ) : (
                          <div />
                        )
                      ) : (
                        /* Data columns: alignment-aware layout (#6) */
                        <div className="h-8 flex items-center gap-0.5">
                          {/* Arrows on left for right-aligned columns */}
                          {enableColumnReordering && colAlign === "right" && (
                            <div className="flex items-center shrink-0">
                              <button
                                type="button"
                                className={cn(
                                  "opacity-0 group-hover/header:opacity-100 transition-opacity p-0.5 hover:bg-accent rounded-sm",
                                  isFirstData && "invisible"
                                )}
                                onClick={() => handleMoveColumn(header.column.id, "left")}
                                disabled={isFirstData}
                                aria-label={t?.moveLeft ?? "Move column left"}
                              >
                                <ChevronLeft className="h-3 w-3" />
                              </button>
                              <button
                                type="button"
                                className={cn(
                                  "opacity-0 group-hover/header:opacity-100 transition-opacity p-0.5 hover:bg-accent rounded-sm",
                                  isLastData && "invisible"
                                )}
                                onClick={() => handleMoveColumn(header.column.id, "right")}
                                disabled={isLastData}
                                aria-label={t?.moveRight ?? "Move column right"}
                              >
                                <ChevronRight className="h-3 w-3" />
                              </button>
                            </div>
                          )}
                          {/* Left arrow for center-aligned columns */}
                          {enableColumnReordering && colAlign === "center" && (
                            <button
                              type="button"
                              className={cn(
                                "opacity-0 group-hover/header:opacity-100 transition-opacity p-0.5 hover:bg-accent rounded-sm shrink-0",
                                isFirstData && "invisible"
                              )}
                              onClick={() => handleMoveColumn(header.column.id, "left")}
                              disabled={isFirstData}
                              aria-label={t?.moveLeft ?? "Move column left"}
                            >
                              <ChevronLeft className="h-3 w-3" />
                            </button>
                          )}

                          {/* Content area */}
                          <div
                            className={cn(
                              "flex-1 min-w-0",
                              colAlign === "center" && "flex justify-center",
                              colAlign === "right" && "flex justify-end"
                            )}
                          >
                            {header.isPlaceholder
                              ? null
                              : flexRender(header.column.columnDef.header, header.getContext())}
                          </div>

                          {/* Both arrows on right for left-aligned columns */}
                          {enableColumnReordering && colAlign === "left" && (
                            <div className="flex items-center shrink-0">
                              <button
                                type="button"
                                className={cn(
                                  "opacity-0 group-hover/header:opacity-100 transition-opacity p-0.5 hover:bg-accent rounded-sm",
                                  isFirstData && "invisible"
                                )}
                                onClick={() => handleMoveColumn(header.column.id, "left")}
                                disabled={isFirstData}
                                aria-label={t?.moveLeft ?? "Move column left"}
                              >
                                <ChevronLeft className="h-3 w-3" />
                              </button>
                              <button
                                type="button"
                                className={cn(
                                  "opacity-0 group-hover/header:opacity-100 transition-opacity p-0.5 hover:bg-accent rounded-sm",
                                  isLastData && "invisible"
                                )}
                                onClick={() => handleMoveColumn(header.column.id, "right")}
                                disabled={isLastData}
                                aria-label={t?.moveRight ?? "Move column right"}
                              >
                                <ChevronRight className="h-3 w-3" />
                              </button>
                            </div>
                          )}
                          {/* Right arrow for center-aligned columns */}
                          {enableColumnReordering && colAlign === "center" && (
                            <button
                              type="button"
                              className={cn(
                                "opacity-0 group-hover/header:opacity-100 transition-opacity p-0.5 hover:bg-accent rounded-sm shrink-0",
                                isLastData && "invisible"
                              )}
                              onClick={() => handleMoveColumn(header.column.id, "right")}
                              disabled={isLastData}
                              aria-label={t?.moveRight ?? "Move column right"}
                            >
                              <ChevronRight className="h-3 w-3" />
                            </button>
                          )}
                        </div>
                      )}

                      {/* Column Resize Handle (#3: wider hit area + z-index) */}
                      {enableColumnResizing && header.column.getCanResize() && (
                        <div
                          onMouseDown={header.getResizeHandler()}
                          onTouchStart={header.getResizeHandler()}
                          onDoubleClick={() => header.column.resetSize()}
                          className={cn(
                            "absolute -right-1 top-0 h-full w-2 cursor-col-resize select-none touch-none z-10",
                            "after:absolute after:right-[3px] after:top-1 after:bottom-1 after:w-px after:bg-border",
                            "hover:after:bg-primary/50 hover:after:w-0.5",
                            header.column.getIsResizing() && "after:bg-primary after:w-0.5"
                          )}
                        />
                      )}
                    </TableHead>
                  )
                })}
              </TableRow>

              {/* Row 2: Filter inputs + bulk actions menu */}
              {enableFiltering && (
                <TableRow className="bg-muted/30">
                  {headerGroup.headers.map((header) => {
                    const meta = header.column.columnDef.meta as { type?: string } | undefined

                    return (
                      <TableHead
                        key={`filter-${header.id}`}
                        className={cn(
                          "py-1.5 px-3",
                          (header.column.id === "select" || header.column.id === "actions") &&
                            "w-[40px] min-w-[40px] max-w-[40px] p-0"
                        )}
                        style={{
                          width: columnWidthMap.get(header.column.id) ?? header.getSize(),
                        }}
                      >
                        {header.column.id === "select" ? (
                          // Empty in filter row (checkbox moved to row 1)
                          <div className="flex justify-center">
                            {hasSelectedRows && (
                              <button
                                type="button"
                                className="hover:bg-accent rounded-sm shrink-0 relative"
                                onClick={cycleSelectionView}
                                aria-label={t?.toggleSelectionView ?? "Toggle selection view"}
                                title={
                                  selectionViewMode === "all"
                                    ? (t?.showAllRows ?? "Show all rows")
                                    : selectionViewMode === "selected"
                                      ? (t?.showSelectedOnly ?? "Showing selected only")
                                      : (t?.showUnselectedOnly ?? "Showing unselected only")
                                }
                              >
                                <Filter
                                  className={cn(
                                    "h-3.5 w-3.5",
                                    selectionViewMode !== "all"
                                      ? "text-primary"
                                      : "text-muted-foreground"
                                  )}
                                />
                                {selectionViewMode === "selected" && (
                                  <Check className="h-2 w-2 absolute -bottom-0.5 -right-0.5 text-primary" />
                                )}
                                {selectionViewMode === "unselected" && (
                                  <XIcon className="h-2 w-2 absolute -bottom-0.5 -right-0.5 text-destructive" />
                                )}
                              </button>
                            )}
                          </div>
                        ) : header.column.id === "actions" ? (
                          <div />
                        ) : header.column.getCanFilter() ? (
                          (() => {
                            if (meta?.type === "boolean") {
                              return (
                                <Select
                                  value={(header.column.getFilterValue() ?? "all") as string}
                                  onValueChange={(val: string) =>
                                    header.column.setFilterValue(val === "all" ? "" : val)
                                  }
                                >
                                  <SelectTrigger className="h-7 text-xs bg-background w-full">
                                    <SelectValue />
                                  </SelectTrigger>
                                  <SelectContent>
                                    <SelectItem value="all">{t?.all ?? "All"}</SelectItem>
                                    <SelectItem value="!*">{t?.empty ?? "Empty"}</SelectItem>
                                    <SelectItem value="true">{t?.yes ?? "Yes"}</SelectItem>
                                    <SelectItem value="false">{t?.no ?? "No"}</SelectItem>
                                  </SelectContent>
                                </Select>
                              )
                            }
                            return (
                              <DebouncedFilterInput
                                value={(header.column.getFilterValue() ?? "") as string}
                                onChange={(value) => header.column.setFilterValue(value)}
                                className="h-7 text-xs bg-background"
                              />
                            )
                          })()
                        ) : (
                          <div />
                        )}
                      </TableHead>
                    )
                  })}
                </TableRow>
              )}
            </React.Fragment>
          ))}
        </TableHeader>
        <TableBody>
          {(() => {
            // Filter rows based on selectionViewMode
            const allRows = table.getRowModel().rows
            const displayRows =
              selectionViewMode === "all"
                ? allRows
                : allRows.filter((row) => {
                    const isSelected = row.getIsSelected()
                    return selectionViewMode === "selected" ? isSelected : !isSelected
                  })

            return displayRows.length ? (
              displayRows.map((row) => (
                <TableRow
                  key={row.id}
                  className={cn(
                    "group/row hover:bg-muted/50 transition-colors cursor-default",
                    onRowClick && "cursor-pointer"
                  )}
                  onClick={() => onRowClick?.(row.original)}
                >
                  {row.getVisibleCells().map((cell) => {
                    const isFixed = cell.column.id === "select" || cell.column.id === "actions"
                    return (
                      <TableCell
                        key={cell.id}
                        className={cn(
                          "px-3 py-2",
                          isFixed && "w-[40px] min-w-[40px] max-w-[40px] p-0"
                        )}
                        style={{
                          width: columnWidthMap.get(cell.column.id) ?? cell.column.getSize(),
                        }}
                      >
                        {flexRender(cell.column.columnDef.cell, cell.getContext())}
                      </TableCell>
                    )
                  })}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell colSpan={table.getAllColumns().length} className="h-24 text-center">
                  {t?.noRecords ?? "No records found."}
                </TableCell>
              </TableRow>
            )
          })()}
        </TableBody>
      </Table>
    </div>
  )
}
